CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity in E.164 form. The phone number is the account: there is no password, only an SMS code.
	"phone_e164" VARCHAR(20) NOT NULL UNIQUE,
	-- First name shown on the card. Deliberately not unique - this is not a handle.
	"display_name" VARCHAR(60) NOT NULL,
	-- Stored as a date, never as an age. Age is derived at query time so nobody has a birthday job to run.
	"birth_date" DATE NOT NULL,
	-- woman | man | nonbinary | other. Free-form enough to extend without a migration.
	"gender" VARCHAR(24) NOT NULL,
	-- Profile text. Null until the user writes one, which most never do.
	"bio" VARCHAR(500),
	-- Optional headline shown under the name.
	"job_title" VARCHAR(120),
	-- Optional education line.
	"school" VARCHAR(120),
	-- Last known latitude, coarsened before storage. Null until location permission is granted.
	"latitude" DECIMAL(9,6),
	-- Last known longitude, coarsened to the same precision as latitude.
	"longitude" DECIMAL(9,6),
	-- False hides the profile from every deck without deleting the account or the existing matches.
	"is_discoverable" BOOLEAN NOT NULL DEFAULT true,
	-- True once a selfie challenge was passed; drives the badge and a ranking boost.
	"is_verified" BOOLEAN NOT NULL DEFAULT false,
	-- Recency signal. Dormant accounts are pushed down the deck rather than removed, so this is read on every candidate query.
	"last_active_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'One row per account. Everything the deck needs to filter on lives here, because candidate selection is the query that has to stay fast.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."phone_e164" IS 'Login identity in E.164 form. The phone number is the account: there is no password, only an SMS code.';
COMMENT ON COLUMN "users"."display_name" IS 'First name shown on the card. Deliberately not unique - this is not a handle.';
COMMENT ON COLUMN "users"."birth_date" IS 'Stored as a date, never as an age. Age is derived at query time so nobody has a birthday job to run.';
COMMENT ON COLUMN "users"."gender" IS 'woman | man | nonbinary | other. Free-form enough to extend without a migration.';
COMMENT ON COLUMN "users"."bio" IS 'Profile text. Null until the user writes one, which most never do.';
COMMENT ON COLUMN "users"."job_title" IS 'Optional headline shown under the name.';
COMMENT ON COLUMN "users"."school" IS 'Optional education line.';
COMMENT ON COLUMN "users"."latitude" IS 'Last known latitude, coarsened before storage. Null until location permission is granted.';
COMMENT ON COLUMN "users"."longitude" IS 'Last known longitude, coarsened to the same precision as latitude.';
COMMENT ON COLUMN "users"."is_discoverable" IS 'False hides the profile from every deck without deleting the account or the existing matches.';
COMMENT ON COLUMN "users"."is_verified" IS 'True once a selfie challenge was passed; drives the badge and a ranking boost.';
COMMENT ON COLUMN "users"."last_active_at" IS 'Recency signal. Dormant accounts are pushed down the deck rather than removed, so this is read on every candidate query.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE INDEX "idx_users_discoverable_active"
ON "users" ("is_discoverable", "last_active_at");
CREATE INDEX "idx_users_location"
ON "users" ("latitude", "longitude");

CREATE TABLE IF NOT EXISTS "user_photos" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the photo.
	"user_id" BIGINT NOT NULL,
	-- CDN URL of the processed image.
	"media_url" VARCHAR(500) NOT NULL,
	-- Order in the card carousel. The row at 0 is the one that appears in the deck.
	"position_index" SMALLINT NOT NULL,
	-- Pixel width, kept so clients can reserve layout space before the image loads.
	"width_px" INTEGER,
	-- Pixel height, same reason.
	"height_px" INTEGER,
	-- pending | approved | rejected. A rejected photo stays in the row so the user can see why it vanished.
	"moderation_status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Upload time.
	"uploaded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "user_photos" IS 'Ordered photos, one row each. The explicit position column - not the upload timestamp - is what makes drag-to-reorder a set of integer updates rather than a rewrite.';
COMMENT ON COLUMN "user_photos"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "user_photos"."user_id" IS 'Owner of the photo.';
COMMENT ON COLUMN "user_photos"."media_url" IS 'CDN URL of the processed image.';
COMMENT ON COLUMN "user_photos"."position_index" IS 'Order in the card carousel. The row at 0 is the one that appears in the deck.';
COMMENT ON COLUMN "user_photos"."width_px" IS 'Pixel width, kept so clients can reserve layout space before the image loads.';
COMMENT ON COLUMN "user_photos"."height_px" IS 'Pixel height, same reason.';
COMMENT ON COLUMN "user_photos"."moderation_status" IS 'pending | approved | rejected. A rejected photo stays in the row so the user can see why it vanished.';
COMMENT ON COLUMN "user_photos"."uploaded_at" IS 'Upload time.';

CREATE UNIQUE INDEX "uq_user_photos_user_position"
ON "user_photos" ("user_id", "position_index");

CREATE TABLE IF NOT EXISTS "user_preferences" (
	-- Owner. Also the primary key, which makes this strictly one row per user.
	"user_id" BIGINT,
	-- Lower bound of the age filter. Never below 18.
	"min_age" SMALLINT NOT NULL DEFAULT 18,
	-- Upper bound of the age filter.
	"max_age" SMALLINT NOT NULL DEFAULT 55,
	-- Search radius in kilometres. Bounded small, because the deck query is a bounding-box scan.
	"max_distance_km" SMALLINT NOT NULL DEFAULT 50,
	-- women | men | everyone. Matched against users.gender when the deck is built.
	"interested_in" VARCHAR(24) NOT NULL DEFAULT 'everyone',
	-- Ignores max_distance_km entirely, which is a different query plan rather than a large radius.
	"show_me_globally" BOOLEAN NOT NULL DEFAULT false,
	-- Suppresses the age on the card without changing what the filter uses.
	"hide_age" BOOLEAN NOT NULL DEFAULT false,
	-- Last preference change; invalidates any cached deck.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id")
);

COMMENT ON TABLE "user_preferences" IS 'Discovery filters, one row per user, keyed by the user id itself. Separate from users because it is written far more often than the profile and read by exactly one query.';
COMMENT ON COLUMN "user_preferences"."user_id" IS 'Owner. Also the primary key, which makes this strictly one row per user.';
COMMENT ON COLUMN "user_preferences"."min_age" IS 'Lower bound of the age filter. Never below 18.';
COMMENT ON COLUMN "user_preferences"."max_age" IS 'Upper bound of the age filter.';
COMMENT ON COLUMN "user_preferences"."max_distance_km" IS 'Search radius in kilometres. Bounded small, because the deck query is a bounding-box scan.';
COMMENT ON COLUMN "user_preferences"."interested_in" IS 'women | men | everyone. Matched against users.gender when the deck is built.';
COMMENT ON COLUMN "user_preferences"."show_me_globally" IS 'Ignores max_distance_km entirely, which is a different query plan rather than a large radius.';
COMMENT ON COLUMN "user_preferences"."hide_age" IS 'Suppresses the age on the card without changing what the filter uses.';
COMMENT ON COLUMN "user_preferences"."updated_at" IS 'Last preference change; invalidates any cached deck.';

CREATE TABLE IF NOT EXISTS "interests" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Canonical tag, e.g. "climbing". Unique so the tag is one node, not one per profile.
	"name" VARCHAR(80) NOT NULL UNIQUE,
	-- Grouping used by the picker UI, e.g. "sports".
	"category" VARCHAR(60),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "interests" IS 'The controlled vocabulary behind shared-interest badges. Canonical rows are what make "you both like climbing" a set intersection instead of string matching.';
COMMENT ON COLUMN "interests"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "interests"."name" IS 'Canonical tag, e.g. "climbing". Unique so the tag is one node, not one per profile.';
COMMENT ON COLUMN "interests"."category" IS 'Grouping used by the picker UI, e.g. "sports".';

CREATE TABLE IF NOT EXISTS "user_interests" (
	-- Member of the pair, part of the composite key.
	"user_id" BIGINT,
	-- Tag of the pair, part of the composite key.
	"interest_id" BIGINT,
	-- When the tag was picked.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id", "interest_id")
);

COMMENT ON TABLE "user_interests" IS 'Join table with a composite primary key and no surrogate id, because nothing ever points at one of these rows.';
COMMENT ON COLUMN "user_interests"."user_id" IS 'Member of the pair, part of the composite key.';
COMMENT ON COLUMN "user_interests"."interest_id" IS 'Tag of the pair, part of the composite key.';
COMMENT ON COLUMN "user_interests"."added_at" IS 'When the tag was picked.';

CREATE INDEX "idx_user_interests_interest"
ON "user_interests" ("interest_id");

CREATE TABLE IF NOT EXISTS "swipes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who swiped.
	"swiper_id" BIGINT NOT NULL,
	-- Who was swiped on.
	"target_id" BIGINT NOT NULL,
	-- left | right | super. A left swipe is recorded, not discarded - it is what keeps the profile out of the deck.
	"direction" VARCHAR(12) NOT NULL,
	-- True when the target was seen during a boost, kept for attributing boost value.
	"is_from_boost" BOOLEAN NOT NULL DEFAULT false,
	-- Swipe time. The only ordering that matters here, and the natural partition key.
	"swiped_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "swipes" IS 'The highest-write table in the product and an append-only log. The unique pair constraint makes a repeated swipe a no-op; the (target, direction) index is what answers "did they already like me?" in one lookup.';
COMMENT ON COLUMN "swipes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "swipes"."swiper_id" IS 'Who swiped.';
COMMENT ON COLUMN "swipes"."target_id" IS 'Who was swiped on.';
COMMENT ON COLUMN "swipes"."direction" IS 'left | right | super. A left swipe is recorded, not discarded - it is what keeps the profile out of the deck.';
COMMENT ON COLUMN "swipes"."is_from_boost" IS 'True when the target was seen during a boost, kept for attributing boost value.';
COMMENT ON COLUMN "swipes"."swiped_at" IS 'Swipe time. The only ordering that matters here, and the natural partition key.';

CREATE UNIQUE INDEX "uq_swipes_swiper_target"
ON "swipes" ("swiper_id", "target_id");
CREATE INDEX "idx_swipes_target_direction"
ON "swipes" ("target_id", "direction");
CREATE INDEX "idx_swipes_swiped_at"
ON "swipes" ("swiped_at");

CREATE TABLE IF NOT EXISTS "matches" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lower of the two user ids. A storage convention, not a role - neither side is the initiator here.
	"user_a_id" BIGINT NOT NULL,
	-- Higher of the two user ids, so the pair is stored exactly once.
	"user_b_id" BIGINT NOT NULL,
	-- The moment the second right swipe landed.
	"matched_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- True when either side of the pair was a super like; the chat shows a different header.
	"is_super_like" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised timestamp of the newest message. Null until someone speaks, which is how the "new matches" row is separated from the chat list.
	"last_message_at" TIMESTAMP,
	-- Set on unmatch. The row is kept so the pair never reappears in either deck.
	"closed_at" TIMESTAMP,
	-- Who unmatched. Null while the match is live, and set null if that account is deleted.
	"closed_by_user_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "matches" IS 'A mutual right swipe, stored once with the ids sorted. It is derivable from two swipe rows and stored anyway, because it is the parent of every message and the thing the chat list pages over.';
COMMENT ON COLUMN "matches"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "matches"."user_a_id" IS 'Lower of the two user ids. A storage convention, not a role - neither side is the initiator here.';
COMMENT ON COLUMN "matches"."user_b_id" IS 'Higher of the two user ids, so the pair is stored exactly once.';
COMMENT ON COLUMN "matches"."matched_at" IS 'The moment the second right swipe landed.';
COMMENT ON COLUMN "matches"."is_super_like" IS 'True when either side of the pair was a super like; the chat shows a different header.';
COMMENT ON COLUMN "matches"."last_message_at" IS 'Denormalised timestamp of the newest message. Null until someone speaks, which is how the "new matches" row is separated from the chat list.';
COMMENT ON COLUMN "matches"."closed_at" IS 'Set on unmatch. The row is kept so the pair never reappears in either deck.';
COMMENT ON COLUMN "matches"."closed_by_user_id" IS 'Who unmatched. Null while the match is live, and set null if that account is deleted.';

CREATE UNIQUE INDEX "uq_matches_pair"
ON "matches" ("user_a_id", "user_b_id");
CREATE INDEX "idx_matches_a_recent"
ON "matches" ("user_a_id", "last_message_at");
CREATE INDEX "idx_matches_b_recent"
ON "matches" ("user_b_id", "last_message_at");

CREATE TABLE IF NOT EXISTS "messages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The match this message lives inside. There is no way to message someone you are not matched with, and this column is why.
	"match_id" BIGINT NOT NULL,
	-- Author. Must be one of the two users on the match.
	"sender_id" BIGINT NOT NULL,
	-- Message text. Null for a media-only or GIF message.
	"body" VARCHAR(2000),
	-- Attached image or GIF. Null for a text message.
	"media_url" VARCHAR(500),
	-- Quoted message within the same match. Null for a normal message.
	"reply_to_message_id" BIGINT,
	-- Send time, the sole ordering key within a match.
	"sent_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the other side opened the thread past this message. Null means unread.
	"read_at" TIMESTAMP,
	-- Soft delete, so a reply pointing at this row does not dangle.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "messages" IS 'Chat, scoped to a match. A single read_at column works here only because a match has exactly two people - a group chat would need a receipts table.';
COMMENT ON COLUMN "messages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "messages"."match_id" IS 'The match this message lives inside. There is no way to message someone you are not matched with, and this column is why.';
COMMENT ON COLUMN "messages"."sender_id" IS 'Author. Must be one of the two users on the match.';
COMMENT ON COLUMN "messages"."body" IS 'Message text. Null for a media-only or GIF message.';
COMMENT ON COLUMN "messages"."media_url" IS 'Attached image or GIF. Null for a text message.';
COMMENT ON COLUMN "messages"."reply_to_message_id" IS 'Quoted message within the same match. Null for a normal message.';
COMMENT ON COLUMN "messages"."sent_at" IS 'Send time, the sole ordering key within a match.';
COMMENT ON COLUMN "messages"."read_at" IS 'When the other side opened the thread past this message. Null means unread.';
COMMENT ON COLUMN "messages"."deleted_at" IS 'Soft delete, so a reply pointing at this row does not dangle.';

CREATE INDEX "idx_messages_match_sent"
ON "messages" ("match_id", "sent_at");

CREATE TABLE IF NOT EXISTS "blocks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who blocked.
	"blocker_id" BIGINT NOT NULL,
	-- Who was blocked.
	"blocked_id" BIGINT NOT NULL,
	-- Optional coarse reason picked in the UI.
	"reason" VARCHAR(40),
	-- Block time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "blocks" IS 'Directed and asymmetric on purpose: the blocked user is never told. Both directions are excluded from the deck, which is why the reverse index exists.';
COMMENT ON COLUMN "blocks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "blocks"."blocker_id" IS 'Who blocked.';
COMMENT ON COLUMN "blocks"."blocked_id" IS 'Who was blocked.';
COMMENT ON COLUMN "blocks"."reason" IS 'Optional coarse reason picked in the UI.';
COMMENT ON COLUMN "blocks"."created_at" IS 'Block time.';

CREATE UNIQUE INDEX "uq_blocks_pair"
ON "blocks" ("blocker_id", "blocked_id");
CREATE INDEX "idx_blocks_blocked"
ON "blocks" ("blocked_id");

CREATE TABLE IF NOT EXISTS "reports" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who reported.
	"reporter_id" BIGINT NOT NULL,
	-- Who was reported.
	"reported_id" BIGINT NOT NULL,
	-- Match the report came from, when it did. Null for a report made straight off a profile card.
	"match_id" BIGINT,
	-- spam | harassment | fake_profile | underage | offline_behaviour | other.
	"category" VARCHAR(40) NOT NULL,
	-- Free-text description from the reporter.
	"details" VARCHAR(1000),
	-- open | reviewing | actioned | dismissed.
	"status" VARCHAR(20) NOT NULL DEFAULT 'open',
	-- Report time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When moderation closed it. Null while open.
	"resolved_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "reports" IS 'The moderation queue. Reports are kept after resolution because the signal that matters is the count against one account over time, not any single row.';
COMMENT ON COLUMN "reports"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "reports"."reporter_id" IS 'Who reported.';
COMMENT ON COLUMN "reports"."reported_id" IS 'Who was reported.';
COMMENT ON COLUMN "reports"."match_id" IS 'Match the report came from, when it did. Null for a report made straight off a profile card.';
COMMENT ON COLUMN "reports"."category" IS 'spam | harassment | fake_profile | underage | offline_behaviour | other.';
COMMENT ON COLUMN "reports"."details" IS 'Free-text description from the reporter.';
COMMENT ON COLUMN "reports"."status" IS 'open | reviewing | actioned | dismissed.';
COMMENT ON COLUMN "reports"."created_at" IS 'Report time.';
COMMENT ON COLUMN "reports"."resolved_at" IS 'When moderation closed it. Null while open.';

CREATE INDEX "idx_reports_reported_status"
ON "reports" ("reported_id", "status");
CREATE INDEX "idx_reports_queue"
ON "reports" ("status", "created_at");

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscriber.
	"user_id" BIGINT NOT NULL,
	-- plus | gold | platinum. The tier decides which recurring entitlements are granted each period.
	"tier" VARCHAR(20) NOT NULL,
	-- active | past_due | cancelled | expired.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- apple | google | web. Renewals arrive from three different webhook shapes.
	"store" VARCHAR(20) NOT NULL,
	-- Store transaction id. Unique, so a replayed renewal receipt cannot double-grant.
	"store_reference" VARCHAR(160) NOT NULL UNIQUE,
	-- Period price in minor units. Integer money, never float.
	"price_minor" INTEGER NOT NULL,
	-- ISO 4217 currency for price_minor.
	"currency_code" CHAR(3) NOT NULL,
	-- When the current period lapses; the renewal job reads this.
	"current_period_end" TIMESTAMP NOT NULL,
	-- First purchase time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscriptions" IS 'Recurring billing. It grants entitlements but never spends them, which keeps refunds and consumption independent.';
COMMENT ON COLUMN "subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscriptions"."user_id" IS 'Subscriber.';
COMMENT ON COLUMN "subscriptions"."tier" IS 'plus | gold | platinum. The tier decides which recurring entitlements are granted each period.';
COMMENT ON COLUMN "subscriptions"."status" IS 'active | past_due | cancelled | expired.';
COMMENT ON COLUMN "subscriptions"."store" IS 'apple | google | web. Renewals arrive from three different webhook shapes.';
COMMENT ON COLUMN "subscriptions"."store_reference" IS 'Store transaction id. Unique, so a replayed renewal receipt cannot double-grant.';
COMMENT ON COLUMN "subscriptions"."price_minor" IS 'Period price in minor units. Integer money, never float.';
COMMENT ON COLUMN "subscriptions"."currency_code" IS 'ISO 4217 currency for price_minor.';
COMMENT ON COLUMN "subscriptions"."current_period_end" IS 'When the current period lapses; the renewal job reads this.';
COMMENT ON COLUMN "subscriptions"."created_at" IS 'First purchase time.';

CREATE INDEX "idx_subscriptions_user_status"
ON "subscriptions" ("user_id", "status");

CREATE TABLE IF NOT EXISTS "entitlement_grants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who the grant belongs to.
	"user_id" BIGINT NOT NULL,
	-- Subscription that produced the grant. Null for a one-off in-app purchase or a promotional gift.
	"subscription_id" BIGINT,
	-- boost | super_like | rewind | passport. One vocabulary for everything consumable.
	"kind" VARCHAR(24) NOT NULL,
	-- Units granted.
	"quantity" INTEGER NOT NULL,
	-- Units left. Decremented in the same transaction that inserts the use row, so a double tap cannot spend the same boost twice.
	"remaining" INTEGER NOT NULL,
	-- subscription | purchase | promo | refund_reversal.
	"source" VARCHAR(24) NOT NULL,
	-- When the units landed.
	"granted_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When unused units lapse. Null for units that never expire.
	"expires_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "entitlement_grants" IS 'A batch of consumables. Balance is the sum of remaining over unexpired grants rather than a single counter, which is what makes expiry and refund reversal expressible at all.';
COMMENT ON COLUMN "entitlement_grants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "entitlement_grants"."user_id" IS 'Who the grant belongs to.';
COMMENT ON COLUMN "entitlement_grants"."subscription_id" IS 'Subscription that produced the grant. Null for a one-off in-app purchase or a promotional gift.';
COMMENT ON COLUMN "entitlement_grants"."kind" IS 'boost | super_like | rewind | passport. One vocabulary for everything consumable.';
COMMENT ON COLUMN "entitlement_grants"."quantity" IS 'Units granted.';
COMMENT ON COLUMN "entitlement_grants"."remaining" IS 'Units left. Decremented in the same transaction that inserts the use row, so a double tap cannot spend the same boost twice.';
COMMENT ON COLUMN "entitlement_grants"."source" IS 'subscription | purchase | promo | refund_reversal.';
COMMENT ON COLUMN "entitlement_grants"."granted_at" IS 'When the units landed.';
COMMENT ON COLUMN "entitlement_grants"."expires_at" IS 'When unused units lapse. Null for units that never expire.';

CREATE INDEX "idx_grants_user_kind_expiry"
ON "entitlement_grants" ("user_id", "kind", "expires_at");

CREATE TABLE IF NOT EXISTS "entitlement_uses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Grant the unit was drawn from, so a refund can reverse exactly what it paid for.
	"grant_id" BIGINT NOT NULL,
	-- Who a super like was aimed at. Null for a boost, which has no target.
	"target_user_id" BIGINT,
	-- Consumption time.
	"used_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- End of the effect window for timed kinds such as a boost. Null for instantaneous ones.
	"expires_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "entitlement_uses" IS 'The spend ledger. Every consumption is a row, so the balance can always be recomputed from history if the remaining counter drifts.';
COMMENT ON COLUMN "entitlement_uses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "entitlement_uses"."grant_id" IS 'Grant the unit was drawn from, so a refund can reverse exactly what it paid for.';
COMMENT ON COLUMN "entitlement_uses"."target_user_id" IS 'Who a super like was aimed at. Null for a boost, which has no target.';
COMMENT ON COLUMN "entitlement_uses"."used_at" IS 'Consumption time.';
COMMENT ON COLUMN "entitlement_uses"."expires_at" IS 'End of the effect window for timed kinds such as a boost. Null for instantaneous ones.';

CREATE INDEX "idx_entitlement_uses_grant_used"
ON "entitlement_uses" ("grant_id", "used_at");

ALTER TABLE "user_photos"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "user_preferences"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "user_interests"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "user_interests"
ADD FOREIGN KEY("interest_id") REFERENCES "interests"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "swipes"
ADD FOREIGN KEY("swiper_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "swipes"
ADD FOREIGN KEY("target_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "matches"
ADD FOREIGN KEY("user_a_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "matches"
ADD FOREIGN KEY("user_b_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "matches"
ADD FOREIGN KEY("closed_by_user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "messages"
